<body>
  <main id="app"></main>
  <script>
    const app = document.querySelector('#app');
    const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
    async function render() {
      if (location.pathname === '/directory') {
        app.innerHTML = `<button id="directory-back" type="button">Projects</button><h1>Task directory</h1>
          <div class="task-filter"><label for="project-scope">Project scope</label><select id="project-scope"><option>Active</option><option>Archived</option></select></div>
          <div class="task-filter"><label for="directory-task-filter">Task filter</label><select id="directory-task-filter"><option>All</option><option>Open</option><option>Completed</option><option>Deleted</option></select></div>
          <div class="task-filter"><label for="directory-priority-filter">Priority filter</label><select id="directory-priority-filter"><option>All</option><option>Low</option><option>Normal</option><option>High</option></select></div>
          <div class="task-filter"><label for="directory-order">Directory order</label><select id="directory-order"><option>Original</option><option>Priority</option><option>Due date</option><option>Title</option></select></div>
          <form class="task-filter" id="directory-range-form" novalidate><label for="directory-due-from">Due from</label><input id="directory-due-from" type="text" placeholder="YYYY-MM-DD"><label for="directory-due-through">Due through</label><input id="directory-due-through" type="text" placeholder="YYYY-MM-DD"><button type="submit">Apply due range</button><p id="directory-range-alert" role="alert" hidden></p></form>
          <form class="search-form" id="directory-search-form"><label for="directory-search">Directory search</label><input id="directory-search" type="text"><button type="submit">Search directory</button></form>
          <div class="directory-bulk-actions"><button id="complete-visible" type="button">Complete visible tasks</button><button id="reopen-visible" type="button">Reopen visible tasks</button></div>
          <section id="directory-results" aria-label="Directory tasks" aria-busy="false"></section><p id="directory-empty" role="status" hidden>No matching tasks</p>`;
        document.querySelector('#directory-back').addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
        const scope = document.querySelector('#project-scope'), taskFilter = document.querySelector('#directory-task-filter'), priority = document.querySelector('#directory-priority-filter'), order = document.querySelector('#directory-order');
        let query = '', from = '', through = '';
        const normalize = value => value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, c => String.fromCharCode(c.charCodeAt(0) + 32));
        const validDate = value => { const m = value.match(/^(\d{4})-(\d{2})-(\d{2})$/); if (!m) return false; const y=+m[1], mo=+m[2], d=+m[3], leap=y%4===0&&(y%100!==0||y%400===0), days=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31]; return y>=1&&mo>=1&&mo<=12&&d>=1&&d<=days[mo-1]; };
        document.querySelector('#directory-search-form').addEventListener('submit', e => { e.preventDefault(); query=document.querySelector('#directory-search').value.trim(); refresh(); });
        document.querySelector('#directory-range-form').addEventListener('submit', e => { e.preventDefault(); const f=document.querySelector('#directory-due-from').value.trim(), t=document.querySelector('#directory-due-through').value.trim(), a=document.querySelector('#directory-range-alert'); if ((f&&!validDate(f))||(t&&!validDate(t))) { a.textContent='Due range must use valid YYYY-MM-DD dates'; a.hidden=false; return; } if(f&&t&&f>t){a.textContent='Due from must not be after Due through';a.hidden=false;return;} from=f;through=t;a.hidden=true;refresh(); });
        const results = document.querySelector('#directory-results');
        const empty = document.querySelector('#directory-empty');
        const completeButton = document.querySelector('#complete-visible'), reopenButton = document.querySelector('#reopen-visible');
        let latestRows = [];
        let refreshSequence = 0;
        async function bulkComplete(completed) {
          const ids = latestRows.filter(x => !!x.completed !== completed).map(x => x.taskId);
          await fetch('/api/directory/bulk-completion', { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ taskIds: ids, completed }) });
          await refresh();
        }
        completeButton.addEventListener('click', () => bulkComplete(true));
        reopenButton.addEventListener('click', () => bulkComplete(false));
        async function refresh() {
          const sequence = ++refreshSequence;
          results.setAttribute('aria-busy', 'true');
          empty.hidden = true;
          completeButton.disabled = true; reopenButton.disabled = true;
          const records=await (await fetch('/api/directory')).json();
          if (sequence !== refreshSequence) return;
          const rows=records.filter(x => !!x.archived === (scope.value==='Archived') && (taskFilter.value==='Deleted'?!!x.deleted:!x.deleted&&(taskFilter.value==='All'||(taskFilter.value==='Open'?!x.completed:!!x.completed))) && (priority.value==='All'||x.priority===priority.value) && normalize(x.title).includes(normalize(query)) && (!from&&!through||!!x.dueDate) && (!from||x.dueDate>=from) && (!through||x.dueDate<=through));
          const originalIndex = new Map(records.map((record, index) => [record.taskId, index]));
          const priorityRank = { High: 0, Normal: 1, Low: 2 };
          const foldedTitle = value => value.replace(/[A-Z]/g, c => String.fromCharCode(c.charCodeAt(0) + 32));
          const compareCodePoints = (left, right) => {
            const a = Array.from(left, c => c.codePointAt(0)), b = Array.from(right, c => c.codePointAt(0));
            for (let i = 0; i < Math.min(a.length, b.length); i++) if (a[i] !== b[i]) return a[i] - b[i];
            return a.length - b.length;
          };
          if (order.value !== 'Original') rows.sort((a, b) => {
            let comparison = 0;
            if (order.value === 'Priority') comparison = priorityRank[a.priority] - priorityRank[b.priority];
            else if (order.value === 'Due date') comparison = !a.dueDate ? (!b.dueDate ? 0 : 1) : (!b.dueDate ? -1 : a.dueDate < b.dueDate ? -1 : a.dueDate > b.dueDate ? 1 : 0);
            else if (order.value === 'Title') comparison = compareCodePoints(foldedTitle(a.title), foldedTitle(b.title));
            return comparison || originalIndex.get(a.taskId) - originalIndex.get(b.taskId);
          });
          latestRows = rows;
